<script>
$(function () {
    var esc = $.fn.dataTable.render.text().display;
    $('#shadow-load').on('click', function () {
        var button = $(this); button.prop('disabled', true).text('กำลังคำนวณ...'); $('#shadow-error').prop('hidden', true); $('#shadow-result').prop('hidden', true);
        $.getJSON('{{ route('wms.stock-valuation.shadow-calculation.data') }}', { allocation_id: $('#shadow-allocation').val(), proposed_unit_cost: $('#shadow-cost').val() }).done(function (r) {
            var s = r.summary || {}, root = r.root || {}, v = r.valuation || {}, variance = r.variance_report || {}, impact = r.recursive_impact_summary || r.impact_summary || {}; $('#shadow-nodes').text((s.affected_nodes || 0) + (s.bridge_replay_nodes || 0)); $('#shadow-delta').text(s.estimated_delta_value || '0.00000000'); $('#shadow-current-value').text(v.current_inventory_value || '0.00000000'); $('#shadow-after-value').text(v.estimated_inventory_value_after_delta || '0.00000000'); $('#shadow-impact-date').text(s.impact_date || '-'); $('#shadow-posting-date').text(s.posting_date || 'ยังไม่กำหนด'); $('#shadow-period-policy').text((s.period_status || 'MISSING') + ' · ' + (s.posting_policy || '-')); $('#shadow-cost-policy').text((s.calculation_method || '-') + ' · ' + (s.cost_policy || '-') + ' · ' + (s.production_output_policy || '-')); $('#shadow-window').text('Impact Window: ' + (s.impact_date || '-') + ' → ' + (s.impact_end_date || '-') + ' · scanned ' + ((s.nodes_scanned || 0) + (s.bridge_replay_nodes || 0)) + ' · production partitions ' + (s.production_replay_partitions || 0) + ' · transfer partitions ' + (s.transfer_replay_partitions || 0) + ' · anchor ' + (s.anchor_date || '-') + ' (' + (s.anchor_status || '-') + ')'); $('#shadow-impact-summary').prop('hidden', !impact).text('Recursive Reconcile: Source ' + (impact.source_delta_value || '0.00000000') + ' = On-hand ' + (impact.ending_on_hand_delta_value || '0.00000000') + ' + Terminal ' + (impact.terminal_delta_value || '0.00000000') + ' + Open Bridge ' + (impact.open_bridge_delta_value || '0.00000000') + ' + Residual ' + (impact.rounding_residual_value || '0.00000000')); $('#shadow-variance').text('Variance Report: ' + (variance.status || 'REQUIRES_REVIEW') + (variance.blockers?.length ? ' · blockers: ' + variance.blockers.join(', ') : '')); $('#shadow-root').html('<span class="badge app-status-info">Read-only</span> Allocation #' + esc(root.allocation_id) + ' · ' + esc(root.source_reference || root.source_type || '-') + ' · ' + esc(root.business_date || '-') + ' · ต้นทุนเดิม ' + esc(root.current_unit_cost || '-') + ' → ใหม่ ' + esc(root.proposed_unit_cost || '-')); var rows = (r.rows || []).map(function (row) { return '<tr><td>#' + esc(row.allocation_id) + '</td><td>' + esc(row.parent_allocation_id || '-') + '</td><td>' + esc(row.lineage_relation || '-') + '</td><td>' + esc(row.business_date || '-') + '</td><td>' + esc(row.source_reference || row.source_type || '-') + '</td><td>' + esc(row.allocation_type + ' / ' + row.direction) + '</td><td>' + esc(row.quantity) + '</td><td>' + esc(row.old_unit_cost) + '</td><td>' + esc(row.estimated_new_unit_cost) + '</td><td>' + esc(row.estimated_delta_value) + '</td><td class="small">' + esc(row.impact_bucket || (row.issues || []).join(', ') || '-') + '</td></tr>'; }).join(''); $('#shadow-rows').html(rows || '<tr><td colspan="11" class="text-center text-secondary">ไม่พบ downstream impact</td></tr>'); var bridges = r.direct_bridges?.edges || []; $('#shadow-bridge-rows').html(bridges.map(function (edge) { return '<tr><td>#' + esc(edge.parent_allocation_id) + '</td><td>#' + esc(edge.child_allocation_id) + '</td><td>' + esc(edge.relation || '-') + '</td><td>' + esc(edge.target_partition_key || '-') + '</td><td>' + esc(edge.estimated_delta_value || '0.00000000') + '</td><td class="small">' + esc((edge.issues || []).join(', ') || 'พร้อม') + '</td></tr>'; }).join('')); $('#shadow-bridge-card').prop('hidden', bridges.length === 0); var productions = r.production_replays?.partitions || []; $('#shadow-production-rows').html(productions.map(function (p) { var i = p.impact_summary || {}; return '<tr><td>' + esc(p.depth) + '</td><td>#' + esc(p.root?.allocation_id || '-') + '</td><td>' + esc(p.source_edge?.target_partition_key || '-') + '</td><td>' + esc(p.summary?.nodes_scanned || 0) + '</td><td>' + esc(i.ending_on_hand_delta_value || '0.00000000') + '</td><td>' + esc(i.open_bridge_delta_value || '0.00000000') + '</td></tr>'; }).join('')); $('#shadow-production-card').prop('hidden', productions.length === 0); var transfers = r.transfer_replays?.partitions || []; $('#shadow-transfer-rows').html(transfers.map(function (p) { var i = p.impact_summary || {}; return '<tr><td>' + esc(p.depth) + '</td><td>#' + esc(p.root?.allocation_id || '-') + '</td><td>' + esc(p.source_edge?.target_partition_key || '-') + '</td><td>' + esc(p.summary?.nodes_scanned || 0) + '</td><td>' + esc(i.ending_on_hand_delta_value || '0.00000000') + '</td><td>' + esc(i.open_bridge_delta_value || '0.00000000') + '</td></tr>'; }).join('')); $('#shadow-transfer-card').prop('hidden', transfers.length === 0); var fifo = r.fifo_evidence || []; $('#shadow-fifo-rows').html(fifo.map(function (layer) { return '<tr><td>#' + esc(layer.layer_id) + '</td><td>#' + esc(layer.source_movement_id) + '</td><td>' + esc(layer.business_date || '-') + '</td><td>' + esc(layer.remaining_quantity || '-') + '</td><td>' + esc(layer.unit_cost || '-') + '</td><td>' + esc(layer.cost_status || '-') + '</td></tr>'; }).join('')); $('#shadow-fifo-card').prop('hidden', fifo.length === 0); $('#shadow-result').prop('hidden', false); }).fail(function (xhr) { $('#shadow-error').text(xhr.responseJSON?.message || 'Shadow Calculation ไม่สำเร็จ').prop('hidden', false); }).always(function () { button.prop('disabled', false).text('คำนวณ Shadow'); });
    });
    window.erpInitSelect2('#shadow-allocation', { ajax: { url: '{{ route('wms.stock-valuation.shadow-calculation.allocation-options') }}', delay: 250, data: function (p) { return { q: p.term || '', page: p.page || 1 }; }, processResults: function (d) { return d; } } }).on('select2:select', function (event) { $('#shadow-cost').val(event.params.data.current_unit_cost || ''); });
